USE [cxView];
GO

CREATE OR ALTER PROCEDURE dbo.SP_TAS009_LISTAR_MENUS_POR_MODULO @idmodulo varchar(36)
AS BEGIN SET NOCOUNT ON;
 SELECT IDMENU,IDMOD,NOMMENU,DESCMENU,ESTMENU,SACRG FROM dbo.TAS009 WHERE IDMOD=LTRIM(RTRIM(@idmodulo)) ORDER BY NOMMENU;
END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS011_LISTAR_SUBMENUS_POR_MENU @idmenu varchar(36)
AS BEGIN SET NOCOUNT ON;
 SELECT IDSUBMENU,IDMENU,NOMSUBMNU,DESCSUBMNU,ESTSUBMNU,SACRG FROM dbo.TAS011 WHERE IDMENU=LTRIM(RTRIM(@idmenu)) ORDER BY NOMSUBMNU;
END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS015_LISTAR_OPCIONES_POR_SUBMENU @idsubmenu varchar(36)
AS BEGIN SET NOCOUNT ON;
 SELECT IDOPCFOMR,IDSUBMENU,IDSMSN,NOMOPC,DESCOPC,ESTOPC,SACRG FROM dbo.TAS015 WHERE IDSUBMENU=LTRIM(RTRIM(@idsubmenu)) ORDER BY NOMOPC;
END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS_USER_ACCESS_GET @iduser varchar(36)
AS BEGIN SET NOCOUNT ON;
 IF NOT EXISTS (SELECT 1 FROM dbo.TAS006 WHERE IDUSER=LTRIM(RTRIM(@iduser))) THROW 50010,'El usuario no existe.',1;
 SELECT ISNULL(a.IDMODUSU,'') ACCESSID,m.IDMOD RESOURCEID,m.IDAPP PARENTID,m.NOMMOD NAME,m.DESCMOD DESCRIPTION,CONVERT(bit,CASE WHEN a.IDMODUSU IS NULL THEN 0 ELSE 1 END) ASSIGNED,CONVERT(bit,CASE WHEN a.ESTMODUSU='A' AND a.SACRG=1 THEN 1 ELSE 0 END) ISACTIVE FROM dbo.TAS007 m LEFT JOIN dbo.TAS008 a ON a.IDMOD=m.IDMOD AND a.IDUSER=LTRIM(RTRIM(@iduser)) WHERE m.SACRG=1 ORDER BY m.NOMMOD;
 SELECT ISNULL(a.IDMENUUSU,'') ACCESSID,m.IDMENU RESOURCEID,m.IDMOD PARENTID,m.NOMMENU NAME,m.DESCMENU DESCRIPTION,CONVERT(bit,CASE WHEN a.IDMENUUSU IS NULL THEN 0 ELSE 1 END) ASSIGNED,CONVERT(bit,CASE WHEN a.ESTMENUUSU='A' AND a.SACRG=1 THEN 1 ELSE 0 END) ISACTIVE FROM dbo.TAS009 m LEFT JOIN dbo.TAS010 a ON a.IDMENU=m.IDMENU AND a.IDUSER=LTRIM(RTRIM(@iduser)) WHERE m.SACRG=1 ORDER BY m.NOMMENU;
 SELECT ISNULL(a.IDSMUSER,'') ACCESSID,s.IDSUBMENU RESOURCEID,s.IDMENU PARENTID,s.NOMSUBMNU NAME,s.DESCSUBMNU DESCRIPTION,CONVERT(bit,CASE WHEN a.IDSMUSER IS NULL THEN 0 ELSE 1 END) ASSIGNED,CONVERT(bit,CASE WHEN a.ESTSMUSER='A' AND a.SACRG=1 THEN 1 ELSE 0 END) ISACTIVE FROM dbo.TAS011 s LEFT JOIN dbo.TAS012 a ON a.IDSUBMENU=s.IDSUBMENU AND a.IDUSER=LTRIM(RTRIM(@iduser)) WHERE s.SACRG=1 ORDER BY s.NOMSUBMNU;
 SELECT ISNULL(a.IDOPCFORMUSU,'') ACCESSID,o.IDOPCFOMR RESOURCEID,o.IDSUBMENU PARENTID,o.NOMOPC NAME,o.DESCOPC DESCRIPTION,CONVERT(bit,CASE WHEN a.IDOPCFORMUSU IS NULL THEN 0 ELSE 1 END) ASSIGNED,CONVERT(bit,CASE WHEN a.ESTOPC='A' AND a.SACRG=1 THEN 1 ELSE 0 END) ISACTIVE FROM dbo.TAS015 o LEFT JOIN dbo.TAS016 a ON a.IDOPCFOMR=o.IDOPCFOMR AND a.IDUSER=LTRIM(RTRIM(@iduser)) WHERE o.SACRG=1 ORDER BY o.NOMOPC;
END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS016_ASIGNAR_OPCION_USUARIO @iduser varchar(36),@idopcion varchar(36),@usuario varchar(20)
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON;
 IF NOT EXISTS(SELECT 1 FROM dbo.TAS006 WHERE IDUSER=LTRIM(RTRIM(@iduser)) AND ESTUSER='A' AND SACRG=1) THROW 50011,'El usuario no existe o no está activo.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.TAS015 WHERE IDOPCFOMR=LTRIM(RTRIM(@idopcion)) AND ESTOPC='A' AND SACRG=1) THROW 50012,'La opción no existe o no está activa.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.TAS015 o JOIN dbo.TAS012 a ON a.IDSUBMENU=o.IDSUBMENU AND a.IDUSER=LTRIM(RTRIM(@iduser)) AND a.ESTSMUSER='A' AND a.SACRG=1 WHERE o.IDOPCFOMR=LTRIM(RTRIM(@idopcion)) AND o.IDSUBMENU IS NOT NULL) THROW 50013,'La opción no tiene un submenú activo asignado al usuario.',1;
 IF EXISTS(SELECT 1 FROM dbo.TAS016 WHERE IDUSER=LTRIM(RTRIM(@iduser)) AND IDOPCFOMR=LTRIM(RTRIM(@idopcion))) UPDATE dbo.TAS016 SET ESTOPC='A',SACRG=1,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDUSER=LTRIM(RTRIM(@iduser)) AND IDOPCFOMR=LTRIM(RTRIM(@idopcion));
 ELSE INSERT dbo.TAS016(IDOPCFORMUSU,IDOPCFOMR,IDUSER,ESTOPC,SACRG,CUSCRT,FCHHRACRT) VALUES(CONVERT(varchar(36),NEWID()),LTRIM(RTRIM(@idopcion)),LTRIM(RTRIM(@iduser)),'A',1,NULLIF(LTRIM(RTRIM(@usuario)),''),SYSDATETIME());
 SELECT TOP(1) IDOPCFORMUSU,IDOPCFOMR,IDUSER,ESTOPC,SACRG,CUSCRT,FCHHRACRT,CULUSA,FCHHRAACT FROM dbo.TAS016 WHERE IDUSER=LTRIM(RTRIM(@iduser)) AND IDOPCFOMR=LTRIM(RTRIM(@idopcion)) ORDER BY FCHHRAACT DESC,FCHHRACRT DESC;
END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS_USER_ACCESS_REMOVE @iduser varchar(36),@idaccess varchar(36),@usuario varchar(20)
AS BEGIN SET NOCOUNT ON; DECLARE @now datetime2(6)=SYSDATETIME(),@found bit=0;
 IF EXISTS(SELECT 1 FROM dbo.TAS008 WHERE IDMODUSU=LTRIM(RTRIM(@idaccess)) AND IDUSER=LTRIM(RTRIM(@iduser))) BEGIN UPDATE dbo.TAS008 SET ESTMODUSU='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=@now WHERE IDMODUSU=LTRIM(RTRIM(@idaccess)) AND IDUSER=LTRIM(RTRIM(@iduser)); SET @found=1; END
 ELSE IF EXISTS(SELECT 1 FROM dbo.TAS010 WHERE IDMENUUSU=LTRIM(RTRIM(@idaccess)) AND IDUSER=LTRIM(RTRIM(@iduser))) BEGIN UPDATE dbo.TAS010 SET ESTMENUUSU='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=@now WHERE IDMENUUSU=LTRIM(RTRIM(@idaccess)) AND IDUSER=LTRIM(RTRIM(@iduser)); SET @found=1; END
 ELSE IF EXISTS(SELECT 1 FROM dbo.TAS012 WHERE IDSMUSER=LTRIM(RTRIM(@idaccess)) AND IDUSER=LTRIM(RTRIM(@iduser))) BEGIN UPDATE dbo.TAS012 SET ESTSMUSER='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=@now WHERE IDSMUSER=LTRIM(RTRIM(@idaccess)) AND IDUSER=LTRIM(RTRIM(@iduser)); SET @found=1; END
 ELSE IF EXISTS(SELECT 1 FROM dbo.TAS016 WHERE IDOPCFORMUSU=LTRIM(RTRIM(@idaccess)) AND IDUSER=LTRIM(RTRIM(@iduser))) BEGIN UPDATE dbo.TAS016 SET ESTOPC='I',SACRG=0,CULUSA=@usuario,FCHHRAACT=@now WHERE IDOPCFORMUSU=LTRIM(RTRIM(@idaccess)) AND IDUSER=LTRIM(RTRIM(@iduser)); SET @found=1; END
 SELECT CONVERT(int,@found) AS RESULTADO;
END;
GO
